public with sharing class Opportunities extends fflib_SObjectDomain
{
    private static final String CLOSED_WON = 'Closed Won';
    private static final String NEGATIVE_MSG = 'Amount cannot be negative.';
    private static final String WON_MSG = 'Amount cannot change on a won opportunity.';

    public Opportunities(List<SObject> records)
    {
        super(records);
    }

    // Insert only
    public override void onValidate()
    {
        for (SObject rec : Records)
        {
            Opportunity opp = (Opportunity) rec;
            if (isNegative(opp))
            {
                error(NEGATIVE_MSG, opp, Schema.Opportunity.Amount);
            }
        }
    }

    // Update only
    public override void onValidate(Map<Id, SObject> existingRecords)
    {
        for (SObject rec : Records)
        {
            Opportunity opp = (Opportunity) rec;
            Opportunity oldOpp = (Opportunity) existingRecords.get(opp.Id);

            if (isNegative(opp))
            {
                error(NEGATIVE_MSG, opp, Schema.Opportunity.Amount);
            }
            else if (oldOpp != null
                && oldOpp.StageName == CLOSED_WON
                && opp.Amount != oldOpp.Amount)
            {
                error(WON_MSG, opp, Schema.Opportunity.Amount);
            }
        }
    }

    private static Boolean isNegative(Opportunity opp)
    {
        return opp.Amount != null && opp.Amount < 0;
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<SObject> sObjectList)
        {
            return new Opportunities(sObjectList);
        }
    }
}
