```apex
public with sharing class HouseholdService {

    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must contain at least one Contact.');
        }
        for (Contact c : members) {
            if (c == null) {
                throw new IllegalArgumentException('members must not contain null entries.');
            }
        }

        Savepoint sp = Database.setSavepoint();
        try {
            // NPSP creates a Household Account (named by NPSP) for each contact without an Account.
            insert members;

            Set<Id> contactIds = new Set<Id>();
            for (Contact c : members) {
                contactIds.add(c.Id);
            }
            Map<Id, Contact> saved = new Map<Id, Contact>(
                [SELECT Id, AccountId FROM Contact WHERE Id IN :contactIds]
            );

            Id primaryContactId = members[0].Id;
            Id householdId = saved.get(primaryContactId).AccountId;
            if (householdId == null) {
                throw new IllegalStateException('NPSP did not create a household for the primary contact.');
            }

            // Move the other members into the first contact's household.
            Set<Id> extraAccountIds = new Set<Id>();
            List<Contact> toMove = new List<Contact>();
            for (Contact c : members) {
                Contact s = saved.get(c.Id);
                if (s.AccountId != householdId) {
                    if (s.AccountId != null) {
                        extraAccountIds.add(s.AccountId);
                    }
                    toMove.add(new Contact(Id = s.Id, AccountId = householdId));
                }
            }
            if (!toMove.isEmpty()) {
                update toMove;
            }

            // Remove leftover households (NPSP may already have deleted some of them).
            if (!extraAccountIds.isEmpty()) {
                List<Account> leftovers = [
                    SELECT Id FROM Account WHERE Id IN :extraAccountIds AND Id != :householdId
                ];
                if (!leftovers.isEmpty()) {
                    delete leftovers;
                }
            }

            // Ensure the first contact is the primary contact.
            Account household = [
                SELECT Id, npe01__One2OneContact__c FROM Account WHERE Id = :householdId
            ];
            if (household.npe01__One2OneContact__c != primaryContactId) {
                household.npe01__One2OneContact__c = primaryContactId;
                update household;
            }

            return householdId;
        } catch (Exception e) {
            Database.rollback(sp);
            throw e;
        }
    }
}
```

